// ============================================================
// nk_three_equation.mod  ——  新凯恩斯三方程模型（完整 .mod）
// 运行：dynare nk_three_equation.mod
// 模型：IS曲线 + NKPC + Taylor规则（满足 Taylor 原理 phi_pi=1.5）
// ============================================================

// ---------- 第 1 块：内生变量声明 ----------
// 所有变量均为偏离稳态的对数/百分点（季度频率）
var  y        // 产出缺口  y_t = Y_t / Y_t^n 的对数偏离
     pi       // 通胀缺口  pi_t （零通胀稳态附近的百分点偏离）
     i        // 名义利率偏离（季度口径，非年化）
     rn       // 自然利率  r_t^n（灵活价格下的实际利率）
     mshock;  // Taylor 规则中的货币政策冲击项（AR(1)）

// ---------- 第 2 块：外生冲击声明 ----------
varexo eps_m    // 货币政策创新：进入 mshock 的白噪声
       eps_rn;  // 自然利率创新：进入 rn 的白噪声

// ---------- 第 3 块：参数声明 ----------
parameters beta sigma phi varphi epsilon theta ...
           kappa phi_pi phi_y rho_rn rho_m;

// ---------- 第 4 块：深参数校准（与 §8 一致） ----------
beta    = 0.99;   // 季度贴现因子，对应年实际利率约 4%
sigma   = 1.0;    // 相对风险厌恶 = 1（log 消费效用）
varphi  = 1.0;    // Frisch 劳动供给弹性的倒数
epsilon = 6.0;    // CES 替代弹性，稳态 markup = epsilon/(epsilon-1) = 1.2
theta   = 0.75;   // Calvo 每期不能调价的厂商比例（季度调价概率 0.25）

// 由深参数推出 NKPC 斜率（在 .mod 里直接算，避免手抄错）
kappa   = (1-theta)*(1-beta*theta)/theta * (sigma+varphi)/(1+epsilon*varphi);

// ---------- 第 5 块：政策参数与冲击持续性 ----------
phi_pi  = 1.5;    // Taylor 规则对通胀的反应（>1，满足 Taylor 原理）
phi_y   = 0.125;  // 对产出缺口的反应（=0.5/4，年度系数季度化）
rho_rn  = 0.9;    // 自然利率冲击 AR(1) 持续性
rho_m   = 0.5;    // 货币政策冲击 AR(1) 持续性

// ---------- 第 6 块：model 块（三方程 + 两个外生过程） ----------
model;
// (1) 前望 IS 曲线
//     y_t = E_t y_{t+1} - (1/sigma)*(i_t - E_t pi_{t+1} - rn_t)
//     直觉：实际利率上升 -> 当期产出缺口下降
y = y(+1) - (1/sigma)*( i - pi(+1) - rn );

// (2) 新凯恩斯菲利普斯曲线 NKPC
//     pi_t = beta*E_t pi_{t+1} + kappa*y_t
//     直觉：正产出缺口 -> 边际成本上升 -> 当期通胀上升
pi = beta*pi(+1) + kappa*y;

// (3) Taylor 规则（含货币政策冲击项 mshock）
//     i_t = phi_pi*pi_t + phi_y*y_t + mshock_t
i = phi_pi*pi + phi_y*y + mshock;

// (4) 自然利率外生 AR(1) 过程
//     rn_t = rho_rn * rn_{t-1} + eps_rn_t
rn = rho_rn*rn(-1) + eps_rn;

// (5) 货币政策冲击项服从 AR(1)
//     mshock_t = rho_m * mshock_{t-1} + eps_m_t
mshock = rho_m*mshock(-1) + eps_m;
end;

// ---------- 第 7 块：稳态初始值（所有对数偏离 = 0） ----------
initval;
y       = 0;
pi      = 0;
i       = 0;
rn      = 0;
mshock  = 0;
end;

// 求解稳态（线性模型下就是原点），并打印 Blanchard-Kahn 诊断
steady;
check;

// ---------- 第 8 块：外新冲击分布 ----------
shocks;
var eps_m   = (0.0025)^2;   // 货币政策冲击标准差约 0.25%（季度利率单位）
var eps_rn  = (0.01)^2;     // 自然利率冲击标准差约 1%
end;

// ---------- 第 9 块：一阶扰动求解，画 40 期 IRF ----------
// order=1：一阶线性近似；irf=40：画 40 个季度的脉冲响应
stoch_simul(order=1, irf=40) y pi i rn mshock;

// === 观测变量声明（与数据列对应） ===
varobs pi i y;

// === 待估参数与先验（estimated_params 块） ===
estimated_params;
phi_pi,  normal_pdf,   1.50, 0.25;
phi_y,   normal_pdf,   0.125,0.05;
theta,   beta_pdf,     0.75, 0.10;
sigma,   normal_pdf,   1.00, 0.25;
varphi,  gamma_pdf,    1.00, 0.50;
rho_rn,  beta_pdf,     0.90, 0.05;
rho_m,   beta_pdf,     0.50, 0.20;
stderr eps_rn, inv_gamma_pdf, 1.00, Inf;
stderr eps_m,  inv_gamma_pdf, 0.25, Inf;
// 稳态通胀与趋势增长（观测方程截距）
pie_star, gamma_pdf,   0.50, 0.10;
gy,      normal_pdf,   0.40, 0.10;
end;

// === 数据文件（三列：pi, i, 产出同比差分，季度） ===
// 数据文件 nk_data.m 或 .xlsx，列顺序与 varobs 一致
// 运行：dynare nk_estimate.mod
estimation(datafile=nk_data, xls_sheet=Sheet1, ...
           mode_compute=6, ...            % 用优化器找后验众数
           mh_replic=200000, ...          % 20万步 MCMC
           mh_nblocks=2, ...              % 2条链
           mh_jscale=0.35, ...            % 提议分布尺度
           first_obs=1, nobs=142, ...     % 1984Q1-2019Q4
           smoothed_state=2, ...
           y) pi i y;                     % 要画IRF的变量

