下面是一个完整可运行的 OccBin .mod，存为zlb_occbin.mod。结构：第一个model;块写"无约束"的 Taylor 规则版；occbin;块声明下界约束；第二个model(linear);块写"绑定"版（利率钉死）。运行dynare zlb_occbin.mod。
[代码块]
// ============================================================
// zlb_occbin.mod  ——  NK 三方程 + 名义利率零下限（OccBin）
// 运行：dynare zlb_occbin.mod
// 思想：两套 model 块分别对应 "约束松弛" 与 "约束绑定"
//       occbin 块声明 i >...
不同 Dynare 版本的 OccBin 语法略有差异：≥4.6 用occbin;块 + 双model块；更早版本用occbin_setup;/occbin_solver;命令式写法。Guerrieri-Iacoviello 官方 replication 文件occbin_example.mod是最权威的对照。若报"inconsistent model blocks"，多半是两个 model 块的变量声明没对齐。

chunks.code:
// ============================================================
// zlb_occbin.mod  ——  NK 三方程 + 名义利率零下限（OccBin）
// 运行：dynare zlb_occbin.mod
// 思想：两套 model 块分别对应 "约束松弛" 与 "约束绑定"
//       occbin 块声明 i >= i_lb，绑定时把 i 钉到下界
// ============================================================

var  y pi i rn ;
varexo eps_rn ;

parameters beta sigma varphi epsilon theta kappa ...
           phi_pi phi_y rho_rn i_lb;

// ---------- 深参数校准（与 NK 三方程页一致） ----------
beta    = 0.99;
sigma   = 1.0;
varphi  = 1.0;
epsilon = 6.0;
theta   = 0.75;
kappa   = (1-theta)*(1-beta*theta)/theta*(sigma+varphi)/(1+epsilon*varphi);
phi_pi  = 1.5;
phi_y   = 0.125;
rho_rn  = 0.90;
i_lb    = 0.0;          // 零下界（对数线性模型里取 0）

// ============================================================
// 【model 块 1】约束【松弛】：Taylor 规则完全生效
// ============================================================
model;
// (1) IS 曲线
y = y(+1) - (1/sigma)*( i - pi(+1) - rn );
// (2) NKPC
pi = beta*pi(+1) + kappa*y;
// (3) Taylor 规则（无下界的"影子"意愿利率）
i = phi_pi*pi + phi_y*y;
// (4) 自然利率 AR(1)
rn = rho_rn*rn(-1) + eps_rn;
end;

// ============================================================
// 【occbin 块】声明偶发约束：名义利率不能低于 i_lb
// ============================================================
occbin;
var i;                          // 被约束的变量
parameters i_lb;                // 下界参数
constraints;
  i >= i_lb;                    // 不等式约束
restrictions;
  i = i_lb;                     // 一旦绑定，把 i 钉到下界（替换 Taylor 规则）
end;

// ============================================================
// 【model 块 2】约束【绑定】：利率钉死在 i_lb
// 只把第三式换成 i = i_lb，其余与块1相同
// ============================================================
model(linear);
y = y(+1) - (1/sigma)*( i - pi(+1) - rn );
pi = beta*pi(+1) + kappa*y;
i = i_lb;                       // 关键区别：不再按 Taylor 规则调
rn = rho_rn*rn(-1) + eps_rn;
end;

// ---------- 初始值（正常稳态原点） ----------
initval;
 y = 0; pi = 0; i = 0; rn = 0;
end;
steady;

// ---------- 自然利率冲击（一次性大负冲击推入 ZLB） ----------
shocks;
var eps_rn; stderr = 0.01;
end;

// 给一个大的负自然利率冲击（-3%），观察经济如何撞入并走出 ZLB
// periods=80：模拟 80 个季度；replic：确定性模拟路径
shocks;
var eps_rn = (-0.03);   // 第 1 期一个 -3% 的自然利率冲击
end;

occbin_setup(display_occbin);
simul(periods=80);

// 想对比"无约束"版本：把 occbin 块与第二个 model 块删掉，
// 直接 stoch_simul 跑块1即可，会看到利率被允许降到负值（错误！）

