下面是一个完整可运行的双部门（部门 1 = 上游，部门 2 = 下游）IO-DSGE。上游部门 1 的中间投入卖给下游部门 2；两部门各有自己的 Calvo 概率 $\theta_1,\theta_2$ 与 TFP 冲击。运行dynare multi_sector.mod。
[代码块]
// ============================================================
// multi_sector.mod  ——  双部门 NK-DSGE + 投入产出链
// 部门1: 上游（如能源/原材料），产品卖给部门2作中间投入
// 部门2: 下游（如制造业），用部门1中间品 + 劳动生产
// 两部门各有：异质 Calvo 概率、异质 TF...
跑出来后重点看eps_z1（上游冲击）那一列：上游 TFP 上升 $\Rightarrow mc_1\downarrow\Rightarrow$ 通过 $a_{12}mc_1$ 使 $mc_2\downarrow\Rightarrow$ 由于部门 2 价格粘（$\theta_2$ 大、$\kappa_2$ 小），$pi_2$ 反应慢而持久——这就是异质粘性 + IO 传导的联合效应。

chunks.code:
// ============================================================
// multi_sector.mod  ——  双部门 NK-DSGE + 投入产出链
// 部门1: 上游（如能源/原材料），产品卖给部门2作中间投入
// 部门2: 下游（如制造业），用部门1中间品 + 劳动生产
// 两部门各有：异质 Calvo 概率、异质 TFP 冲击
// 运行：dynare multi_sector.mod
// ============================================================

// ---------- 内生变量（部门1 下标1，部门2 下标2） ----------
var  y1 y2          // 两部门产出缺口
     pi1 pi2        // 两部门部门通胀
     pi             // 总体通胀（消费篮子加权）
     mc1 mc2        // 两部门实际边际成本
     n1 n2          // 两部门就业
     w              // 共同实际工资
     rrn            // 自然利率（需求侧）
     z1 z2          // 两部门对数 TFP（外生状态）
     i              // 名义政策利率（总体 Taylor 规则）
     p1_rel p2_rel; // 部门相对价格（这里取相对偏离）

// ---------- 外生冲击 ----------
varexo eps_z1 eps_z2 eps_d;

// ---------- 参数 ----------
parameters beta sigma varphi epsilon ...
           theta1 theta2        // 两部门异质 Calvo 概率
           k1 k2                // 两部门 NKPC 斜率（由 theta 推）
           a12                  // 部门2 每单位产出用部门1中间品的份额
           alpha2               // 部门2 劳动份额（1-alpha2 即中间品份额）
           b1 b2                // 部门1、2在消费篮子中的权重（b1+b2=1）
           phi_pi phi_y rho_z rho_d;

// ---------- 校准 ----------
beta    = 0.99;
sigma   = 1.0;
varphi  = 1.0;
epsilon = 6.0;

// 部门1（上游/能源）价格调得勤 -> theta1 小；
// 部门2（下游/制造）价格粘 -> theta2 大
theta1  = 0.55;     // 上游约 2 季度调一次价
theta2  = 0.80;     // 下游约 5 季度调一次价
k1 = (1-theta1)*(1-beta*theta1)/theta1;   // 上游 NKPC 斜率大（灵活）
k2 = (1-theta2)*(1-beta*theta2)/theta2;   // 下游 NKPC 斜率小（粘性）

// 投入产出关键参数：a12 = 部门2 用部门1 中间品的份额
a12     = 0.35;     // 下游 35% 成本来自购买上游中间品
alpha2  = 0.65;     // 下游 65% 成本来自劳动（1-alpha2-a12=0 简化）
b1      = 0.30;     // 上游最终品占消费篮子 30%
b2      = 0.70;     // 下游最终品占消费篮子 70%

phi_pi  = 1.5;
phi_y   = 0.125;
rho_z   = 0.90;
rho_d   = 0.80;

// ---------- model 块 ----------
model;
// (1) 部门1 边际成本：只用劳动（上游不买别人中间品，简化）
//     mc1 = varphi*n1 + sigma*y1 - z1   （单部门劳动-边际成本桥）
mc1 = varphi*n1 + sigma*y1 - z1;

// (2) 部门2 边际成本：关键！含 IO 传导
//     部门2 成本 = 工资项 + 上游部门1 价格/成本项（权重 a12）
//     即 Eq.M4：mc2 = alpha2*w + a12*mc1 - z2
mc2 = alpha2*w + a12*mc1 - z2;

// (3) 部门1 NKPC（斜率 k1 大 -> 灵活）
pi1 = beta*pi1(+1) + k1*mc1;

// (4) 部门2 NKPC（斜率 k2 小 -> 粘）
pi2 = beta*pi2(+1) + k2*mc2;

// (5) 总体通胀 = 消费篮子加权（Eq.M7 聚合）
pi  = b1*pi1 + b2*pi2;

// (6) 共同工资与部门就业的劳动供给桥（简化：w = varphi*n + sigma*y）
//     两部门在统一劳动市场上竞争
w   = varphi*n1 + sigma*y1;
w   = varphi*n2 + sigma*y2;   // 同一工资，两边都满足（冗余恒等，供 Dynare 求解）

// (7) 资源 / 需求侧（简化 IS：总体产出缺口由实际利率调节）
y1 = y1(+1) - (1/sigma)*( i - pi(+1) - rrn );
y2 = y2(+1) - (1/sigma)*( i - pi(+1) - rrn );

// (8) 货币政策：总体 Taylor 规则
i = phi_pi*pi + phi_y*(b1*y1 + b2*y2);

// (9) 部门 TFP 外生过程
z1 = rho_z*z1(-1) + eps_z1;
z2 = rho_z*z2(-1) + eps_z2;

// (10) 需求侧自然利率
rrn = rho_d*rrn(-1) + eps_d;
end;

// ---------- 稳态初始值（全 0，对数偏离） ----------
initval;
 y1=0; y2=0; pi1=0; pi2=0; pi=0; mc1=0; mc2=0;
 n1=0; n2=0; w=0; rrn=0; z1=0; z2=0; i=0;
end;
steady;
check;

// ---------- 冲击分布 ----------
shocks;
var eps_z1 = (0.01)^2;    // 上游 TFP 冲击
var eps_z2 = (0.01)^2;     // 下游 TFP 冲击
var eps_d  = (0.01)^2;     // 总需求冲击
end;

// ---------- 求解并画 IRF（40 期） ----------
// 重点观察：eps_z1（上游能源）如何通过 a12 传导到 mc2 -> pi2 -> 总体 pi
stoch_simul(order=1, irf=40) y1 y2 pi1 pi2 pi mc1 mc2 i;
